package com.skillswap.controller;
import com.skillswap.model.*; import com.skillswap.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reviews") public class ReviewController {private final ReviewRepository reviews;private final UserRepository users; public ReviewController(ReviewRepository r,UserRepository u){reviews=r;users=u;} @GetMapping("/{userId}") public List<Review> get(@PathVariable Long userId){return reviews.findByReviewedUserId(userId);} @PostMapping public Review add(@RequestBody Map<String,Object> x){Review r=new Review();r.setReviewer(users.findById(Long.valueOf(x.get("reviewerId").toString())).orElseThrow());r.setReviewedUser(users.findById(Long.valueOf(x.get("reviewedUserId").toString())).orElseThrow());r.setRating(Integer.parseInt(x.get("rating").toString()));r.setComment(x.get("comment").toString());return reviews.save(r);} }
